* { box-sizing: border-box; }

.cat-clock-widget {
  width: 100%;
  height: 100%;
  min-height: 190px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent !important;
  overflow: visible;
  position: relative;
  color: #fff;
  font-family: Arial, "Helvetica Neue", "PingFang SC", "Microsoft YaHei", sans-serif;
  user-select: none;
}

/* 时间本体：放在猫下面，让猫可以自然压在数字上 */
.clock-content {
  position: relative;
  z-index: 5;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding-top: 2px;
}

.time {
  font-size: clamp(110px, 13vw, 136px);
  line-height: .84;
  font-weight: 800;
  letter-spacing: -.065em;
  color: #fff;
  white-space: nowrap;
  text-shadow: 0 4px 8px rgba(55,65,80,.28), 0 0 2px rgba(255,255,255,.8);
  position: relative;
  z-index: 5;
}

.date {
  margin-top: 13px;
  font-size: clamp(26px, 3.2vw, 30px);
  line-height: 1;
  font-weight: 500;
  letter-spacing: .07em;
  color: #fff;
  white-space: nowrap;
  text-shadow: 0 3px 6px rgba(55,65,80,.23), 0 0 2px rgba(255,255,255,.6);
  position: relative;
  z-index: 5;
}

/*
 * 装饰层必须高于时间：这样右上角小猫会真正“趴”在数字上。
 * 保持原图比例，只轻微压缩中间空白，让左右爪形成包裹。
 */
.decoration {
  position: absolute;
  z-index: 10;
  left: 50%;
  top: 41%;
  width: min(690px, 118vw);
  aspect-ratio: 1467 / 624;
  transform: translate(-50%, -50%) scaleX(.84);
  transform-origin: center center;
  pointer-events: none;
  overflow: visible;
}

.decoration img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
}

@media (max-width: 520px) {
  .cat-clock-widget {
    min-height: 180px;
  }

  .time {
    font-size: 116px;
  }

  .date {
    margin-top: 13px;
    font-size: 26px;
  }

  .decoration {
    width: min(690px, 118vw);
    top: 41%;
    transform: translate(-50%, -50%) scaleX(.82);
  }
}

/* v5: separate the cat from the side accents to avoid clipping its ears. */
.cat-clock-widget {
  --cat-art-width: min(690px, 118vw);
  --cat-art-height: calc(var(--cat-art-width) * 0.4253578732);
  isolation: isolate;
}
.cat-clock-widget > .clock-content { z-index: 1; }
.cat-clock-widget > .decoration {
  width: var(--cat-art-width);
  height: var(--cat-art-height);
  z-index: 20;
}
.cat-clock-widget > .decoration-sides {
  top: calc(41% - 12px);
  clip-path: polygon(0 0, 69% 0, 69% 52%, 100% 52%, 100% 100%, 0 100%);
}
.cat-clock-widget > .decoration-cat {
  top: max(calc(41% - 12px), calc(var(--cat-art-height) * .5 + 4px));
  z-index: 21;
  clip-path: polygon(69% 0, 100% 0, 100% 52%, 69% 52%);
}
.cat-clock-widget > .decoration-sides {
  top: calc(41% - 29px);
}

.cat-clock-widget > .decoration-cat {
  top: max(
    calc(41% - 29px),
    calc(var(--cat-art-height) * .5 + 4px)
  );
}

