--console-shell-z: 10;
}

/* === 2. 我方最后一条消息智能避让胶囊 === */
/* 只有在输入框为空（胶囊存在）时，才往上顶。打字时胶囊消失，气泡自动掉下来 */
.chat-detail-screen:has(.input-box-custom:placeholder-shown) [data-absolute-last="true"][data-sender="me"] {
margin-bottom: 30px !important; /* 觉得不够远可以自己改大 */
}
/* === 2. 胶囊智能躲避：让 CSS 自己做加法（修复重叠bug） === */
.chat-detail-screen {
--offset-reply: 0px;
--offset-sendas-char: 0px;
--offset-sendas-narr: 0px;
--offset-console: 0px;
}
/* 各自独立报身高，绝不混淆 */
.chat-detail-screen:has(.input-reply-preview-bar) { --offset-reply: 50px; }
.chat-detail-screen:has(.input-sendas-char-bar) { --offset-sendas-char: 40px; }
.chat-detail-screen:has(.input-sendas-narration-bar) { --offset-sendas-narr: 40px; }
.chat-detail-screen:has(.nuo-console-shell) { --offset-console: 45px; }
/* 胶囊自动往上飞，高度 = 所有出现的条的高度总和 */
.input-btn-mic, .input-btn-sticker {
margin-top: calc(-1 * (var(--offset-reply) + var(--offset-sendas-char) + var(--offset-sendas-narr) + var(--offset-console))) !important;
/* 胶囊自动往上飞，并强行统一两半边的动画 */
.input-btn-mic, .input-btn-sticker {
margin-top: calc(-1 * (var(--offset-reply) + var(--offset-sendas-char) + var(--offset-sendas-narr) + var(--offset-console))) !important;
transition: all 0.2s cubic-bezier(0.25, 0.8, 0.25, 1) !important;}
}
/* 控制台出现时，保证胶囊在最上层不被盖住 */
.chat-detail-screen:has(.nuo-console-shell) .input-btn-mic,
.chat-detail-screen:has(.nuo-console-shell) .input-btn-sticker {
z-index: 50 !important;
}

/* === 3. 我方气泡避让胶囊 === */
/* 没打字（胶囊在）时，气泡往上躲 30px；一打字（胶囊消失），气泡自动掉下来 */
.chat-detail-screen:has(.input-box-custom:placeholder-shown) [data-absolute-last="true"][data-sender="me"] {
margin-bottom: 30px !important;
transition: margin-bottom 0.2s ease !important; /* 掉下来的时候也丝滑一点 */
}
/* === 气泡底部便签虚线（首尾封边 + 左右分色版） === */
/* 1. 给第一条、最后一条、单条气泡腾出底部空间 */
.msg-bubble-wrapper.is-first .bubble-them-custom,
.msg-bubble-wrapper.is-last .bubble-them-custom,
.msg-bubble-wrapper.is-single .bubble-them-custom,
.msg-bubble-wrapper.is-first .bubble-me-custom,
.msg-bubble-wrapper.is-last .bubble-me-custom,
.msg-bubble-wrapper.is-single .bubble-me-custom {
position: relative !important;
padding-bottom: 10px !important;
}

/* 2. 对方气泡（左边）的虚线：稍微加深一点的灰（用半透明黑） */
.msg-bubble-wrapper.is-first .bubble-them-custom::after,
.msg-bubble-wrapper.is-last .bubble-them-custom::after,
.msg-bubble-wrapper.is-single .bubble-them-custom::after {
content: "";
position: absolute;
left: 12px;
right: 12px;
bottom: 7px;
border-bottom: 1px dashed rgba(0, 0, 0, 0.12) !important; /* 嫌淡把0.12改大，比如0.15 */
pointer-events: none;
}
/* 3. 我方气泡（右边）的虚线：专属蓝色加透明度 */
.msg-bubble-wrapper.is-first .bubble-me-custom::after,
.msg-bubble-wrapper.is-last .bubble-me-custom::after,
.msg-bubble-wrapper.is-single .bubble-me-custom::after {
content: "";
position: absolute;
left: 12px;
right: 12px;
bottom: 7px;
border-bottom: 1px dashed rgba(155, 196, 226, 0.6) !important; /* 嫌深把0.6改小，比如0.4 */
pointer-events: none;
}
/* === 独立翻译条（往内缩 + 浅蓝色统一版） === */
:root {
--translation-always-show: 1;
}
.msg-translation-wrapper { display: none !important; }

.msg-translation-detached {
display: block !important;
margin-top: 4px !important;
}

/* 对方的翻译整体往右挪一点 */
.msg-translation-detached-them {
margin-left: 4px !important; 
}

/* 文字变成浅蓝色 */
.msg-translation-detached-content {
background: transparent !important;
color: #c4d8e8 !important; /* 浅蓝色文字 */
padding: 4px 0 4px 12px !important;
font-size: 13px !important;
position: relative !important;
box-shadow: none !important;
}

/* 竖条也变成一样的浅蓝色 */
.msg-translation-detached-content::before {
content: "" !important;
position: absolute !important;
left: 0 !important;
top: 6px !important;
bottom: 6px !important;
width: 4px !important;
border-radius: 4px !important;
background-color: #c4d8e8 !important; /* 浅蓝色竖条 */
}

/* 把装了图片/表情包的气泡背景和边框变透明（排除引用框里的图片） */
.bubble-me-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img)),
.bubble-them-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img)) {
background: transparent !important;
border: none !important;
box-shadow: none !important;
padding: 0 !important;
}
/* 去掉图片/表情包底部的虚线（同样排除） */
.bubble-me-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img))::after,
.bubble-them-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img))::after {
display: none !important;
}
/* 控制图片大小 + 修复位置 */
.msg-bubble-container img {
max-width: 110px !important; 
max-height: 170px !important;
width: auto !important;
height: auto !important;
object-fit: contain !important;
border-radius: 8px !important;
}
/* 我发的图片靠右贴头像 */
.msg-me .msg-bubble-container img {
display: block !important;
margin-left: auto !important;
}
/* 对方发的图片靠左贴头像 */
.msg-them .msg-bubble-container img {
display: block !important;
margin-right: auto !important;
}
/* 强制缩小引用框里的图片并裁成正方形 */
.msg-bubble-wrapper .msg-reply-block-detached img,
.msg-reply-detached-text img {
    width: 28px !important;
    height: 28px !important;
    max-width: 28px !important; 
    max-height: 28px !important;
    object-fit: cover !important; /* 👈 关键：填满并裁剪 */
    aspect-ratio: 1 / 1 !important; /* 👈 强制正方形 */
    border-radius: 3px !important;
    vertical-align: middle !important;
    display: inline-block !important;
    margin: 0 4px !important;
}
/* 引用框内容顶部齐平 */
.msg-reply-block-detached {
    align-items: flex-start !important; 
}
/* 名字稍微往下压一点，和图片视觉边缘对齐 */
.msg-reply-detached-name {
    margin-top: 0px !important; 
}

data.css:
/* ================= 全局容器 ================= */
.mz-top-bubble-widget {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center; /* 气泡永远在组件正中间 */
  padding: 5%; 
  background: transparent; /* 最外层全透明 */
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;

  /* 变量兜底 */
  --bg-color: #ffffff;
  --border-color: #333333;
  --text-color: #333333;
}

/* ================= 核心：对话气泡外框 ================= */
.bubble-frame {
  position: relative;
  background-color: var(--bg-color);

  /* 还原原图：1.5px 粗细的实线边框，16px的圆角 */
  border: 1.5px solid var(--border-color); 
  border-radius: 16px; 

  /* 自适应内部文字大小的留白 */
  padding: 12px 24px;

  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 10px rgba(0,0,0,0.03); /* 微微的一点环境光阴影，更立体 */
}

/* 🌟 基础尖角方块 */
.bubble-frame::before {
  content: '';
  position: absolute;
  left: 50%;
  width: 12px;
  height: 12px;
  background-color: var(--bg-color);
  transform: translateX(-50%) rotate(45deg);
}

/* 🌟 状态 1：尖角朝上 */
.bubble-frame.pos-top::before {
  top: -7.5px; 
  border-top: 1.5px solid var(--border-color);
  border-left: 1.5px solid var(--border-color);
  border-top-left-radius: 3px; /* 顶部圆润处理 */
}

/* 🌟 状态 2：尖角朝下 */
.bubble-frame.pos-bottom::before {
  bottom: -7.5px; 
  border-bottom: 1.5px solid var(--border-color);
  border-right: 1.5px solid var(--border-color);
  border-bottom-right-radius: 3px; /* 底部圆润处理 */
}

/* ================= 文字排版 ================= */
.bubble-text {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-color);
  letter-spacing: 1px;
  text-align: center;

  /* 防止文字太长撑爆，设置最大宽度并允许换行 */
  max-width: 100%;
  word-wrap: break-word;
  white-space: pre-wrap;

  /* 将文字层级调高，防止被伪元素影响 */
  position: relative;
  z-index: 2;
}

/*⁣‌⁠⁠⁠‌‍‌⁠​‍‌‌​⁠⁠​‌‌​⁠⁠‍​‌⁠‍‍​‌⁠‌​‌⁠​⁠‍​⁠‍‌⁠‍‍⁠‍​⁠​‍⁠​⁠‍​‍‍⁠‍‌⁠‍‌⁠⁣ ================= 基础设定 ================= */
.mz-post-widget {
  width: 100%; height: 100%; position: relative;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif;
  background-color: transparent !important;
  box-sizing: border-box; overflow: hidden;
}
img { object-fit: cover; display: block; width: 100%; height: 100%; }

/* ================= 底部卡片面板 ================= */
.card-wrapper {
  position: absolute;
  top: 14%; bottom: 3%; left: 4%; right: 4%;
  border-radius: 20px;
  overflow: hidden;
  border: 1px solid var(--color-line); 
  box-shadow: none !important;
}

.bg-layer { position: absolute; top: 0; left: 0; right: 0; bottom: 0; z-index: 0; }

.card-content {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0; z-index: 1;
  display: flex; flex-direction: column;
  padding: 4.5% 6% 3.5% 6%;
  box-sizing: border-box;
}

.header-row {
  display: flex; justify-content: space-between; align-items: center;
  padding-left: 27%;
  height: 28px; flex-shrink: 0;
}
.header-name { color: var(--color-name); font-weight: 800; }
.header-day { color: var(--color-date); font-weight: 600; font-size: 11px; padding-bottom: 2px; border-bottom: 1px solid var(--color-line); }

.divider { width: 100%; height: 1px; background-color: var(--color-line); margin: 3% 0; flex-shrink: 0; }

/* ================= 列表区 ================= */
.post-list { flex: 1; display: flex; flex-direction: column; justify-content: center; gap: 6%; min-height: 0; }
.post-item { display: flex; align-items: flex-start; height: 45%; }
.post-img { width: 36%; height: 100%; border-radius: 12px; background-color: #f5f5f5; overflow: hidden; flex-shrink: 0; margin-right: 4%; }
.post-info { flex: 1; display: flex; flex-direction: column; height: 100%; min-width: 0; }
.post-title-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; }
.post-tag { color: var(--color-tag); font-weight: 800; }
.post-icons { display: flex; gap: 8px; color: var(--color-date); }
.post-icons svg { width: 13px; height: 13px; }
.post-desc { color: var(--color-desc); font-weight: 800; line-height: 1.3; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.bullet { font-weight: 900; margin-right: 2px; }
.date-row { text-align: right; color: var(--color-date); font-weight: 600; letter-spacing: 0.5px; }

/* ================= 底部评论区 ================= */
.footer-comment { height: 42px; flex-shrink: 0; } 
.comment-inner { width: 100%; height: 100%; border: 1.5px solid var(--color-line); border-radius: 40px; display: flex; align-items: center; padding: 0 12px; box-sizing: border-box; }
.avatar-box-bottom { width: 26px; height: 26px; border-radius: 50%; background-color: #eee; border: 1px solid var(--color-line); margin-right: 8px; flex-shrink: 0; overflow: hidden; } 
.comment-text { color: var(--color-comment); font-weight: 600; flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 1.05em; } 
.comment-expand { width: 24px; height: 24px; background-color: var(--color-line); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; } 
.comment-expand svg { width: 12px; height: 12px; }

/* ================= 🌟 悬浮大头像组 ================= */
.floating-avatar-group {
  position: absolute;
  top: 14%; left: 9%;
  transform: translateY(-50%); 
  display: inline-block;
  z-index: 10;
}

.avatar-box-main {
  width: clamp(72px, 21vw, 90px); 
  height: clamp(72px, 21vw, 90px);
  border-radius: 50%;
  background-color: #f0f0f0;
  border: 1px solid #ffffff; 
  box-shadow: none;
  overflow: hidden;
  position: relative;
  z-index: 2;
}

/* 🌟 核心调优：加粗虚线框（1.5px），防止在一些屏幕上发虚 */
.status-bubble {
  position: absolute;
  bottom: 78%; left: 72%;
  background-color: #ffffff;
  border: 1.5px dashed var(--color-date); 
  border-radius: 10px;
  padding: 4px 6px; 
  display: flex; align-items: center; gap: 3px;
  z-index: 3; 
  white-space: nowrap;
}
.status-bubble span { color: var(--color-desc); font-weight: 800; font-size: 10px; line-height: 1; }
.status-bubble .status-icon { width: 9px; height: 9px; color: var(--color-desc); }

/* 🌟 全新 SVG 矢量小尾巴：无缝嵌入，极其平滑 */
.bubble-tail {
  position: absolute;
  bottom: -7.5px; 
  left: 8px;
  width: 14px; 
  height: 8px;
  color: var(--color-date); /* 颜色自动跟随时钟/日期变量 */
  display: block;
}

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background-color: transparent !important;
  font-family: -apple-system, "Helvetica Neue", sans-serif;
}

.widget-container {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  position: relative;
  box-sizing: border-box;
}

.bubble {
  background-color: #ffffff;
  border: 1px solid #ececec;
  border-radius: 40px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.03);
  box-sizing: border-box;
}

/* 頂部氣泡 */
.top-bubble {
  display: flex;
  align-items: center;
  /* 【修改】頭像與外框的間距 (上下左 padding) 從 6px 增加到了 9px */
  padding: 9px 14px 9px 9px; 
  width: 90%; 
  max-width: 320px;
  z-index: 1; 
  /* 【修改】將上方的框整體向左平移 5px */
  transform: translateX(-5px); 
}

.avatar-container {
  position: relative;
  width: 38px;
  height: 38px;
  flex-shrink: 0;
}

.avatar {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
  background-color: #f0f0f0;
}

.badge {
  position: absolute;
  top: -2px;
  right: -2px;
  background-color: #ffdae9;
  color: #ffffff;
  font-size: 9px;
  font-weight: bold;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.text-content {
  margin-left: 10px;
