}

.actions {
  display: flex;
  gap: 8px;
}

.icon-btn {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.pink-bg { background-color: #ffe6f0; }
.gray-bg { background-color: #d8d8d8; }

/* 底部疊加氣泡 */
.bottom-bubble {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px 8px 20px;
  width: 88%; 
  max-width: 310px;
  align-self: flex-end;
